5878  md_leave_child_containers(MD_CTX* ctx, int n_keep)
  5879  {
  5880      int ret = 0;
  5881
  5882      while(ctx->n_containers > n_keep) {
  5883          MD_CONTAINER* c = &ctx->containers[ctx->n_containers-1];
  5884          int is_ordered_list = FALSE;
  5885
  5886          switch(c->ch) {
  5887              case _T(')'):
  5888              case _T('.'):
  5889                  is_ordered_list = TRUE;
  5890                  MD_FALLTHROUGH();
  5891
  5892              case _T('-'):
  5893              case _T('+'):
  5894              case _T('*'):
  5895                  MD_CHECK(md_push_container_bytes(ctx, MD_BLOCK_LI,
  5896                                  c->task_mark_off, (c->is_task ? CH(c->task_mark_off) : 0),
  5897                                  MD_BLOCK_CONTAINER_CLOSER));
  5898                  MD_CHECK(md_push_container_bytes(ctx,
  5899                                  (is_ordered_list ? MD_BLOCK_OL : MD_BLOCK_UL), 0,
  5900                                  c->ch, MD_BLOCK_CONTAINER_CLOSER));
  5901                  break;
  5902
  5903              case _T('>'):
  5904                  MD_CHECK(md_push_container_bytes(ctx,
  5905                                  (c->is_admonition ? MD_BLOCK_ADMONITION : MD_BLOCK_QUOTE),
  5906                                  0, 0, MD_BLOCK_CONTAINER_CLOSER));
  5907                  break;
  5908
  5909              default:
  5910                  MD_UNREACHABLE();
  5911                  break;
  5912          }
  5913
  5914          ctx->n_containers--;
  5915      }
  5916
  5917  abort:
  5918      return ret;
